Voici un exemple de code C# pour créer un serveur HTTP avec `HttpListener` qui répond à la demande "GET /hello" sur le port 8080 :
```csharp
using System;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading;

class HelloServer
{
    static void Main(string[] args)
    {
        // Créer un objet HttpListener
        HttpListener listener = new HttpListener();

        // Configurer l'écouteur pour écouter les requêtes sur le port 8080
        listener.Port = 8080;
        listener.Prefixes.Add("http://localhost:8080/");

        // Démarrez la liste énattendent des requêtes
        listener.Start();

        Console.WriteLine("Serveur écoutant sur le port 8080...");

        while (true)
        {
            // Accepte une requête
            HttpListenerContext context = listener.GetContext();
            HttpListenerRequest request = context.Request;

            // Vérifiez si la requête est pour la page "hello"
            if (request.Url.AbsolutePath == "/hello")
            {
                // Répondre à la requête avec le contenu "Hello World!"
                string response = "Hello World!";
                context.Response.ContentType = "text/plain";
                byte[] buffer = Encoding.UTF8.GetBytes(response);
                context.Response.OutputStream.Write(buffer, 0, buffer.Length);
                context.Response.OutputStream.Close();
            }
            else
            {
                // Répondre à la requête avec un code d'erreur 404 (Not Found)
                context.Response.StatusCode = 404;
                context.Response.StatusDescription = "Not Found";
            }
        }
    }
}
```
