package main

import (
	"fmt"
	"net/http"

	"github.com/refit/refit/v3"
)

const (
	apiUrl string = "https://api.example.com"
	endpoint string = "/users"
)

type User struct {
	ID   int    `json:"id"`
	Name string `json:"name"`
}

func main() {
	client := refit.New(http.Client{})

	// Create an interface for the API endpoint
	type UserAPI interface {
		GetUsers() ([]User, *http.Response, error)
	}

	// Implement the interface using Refit
	var api UserAPI
	refitRef := client.ForInterface(api, apiUrl)

	// Make the GET request
	resp, err := refitRef.GetUsers()
	if err != nil {
		fmt.Println(err)
		return
	}

	// Check the response status code
	if resp.StatusCode != http.StatusOK {
		fmt.Printf("Error: %s\n", resp.Status)
		return
	}

	// Unmarshal the response body into a slice of User structs
	var users []User
	err = json.NewDecoder(resp.Body).Decode(&users)
	if err != nil {
		fmt.Println(err)
		return
	}

	// Print the users
	fmt.Println(users)
}
