    Node* raiz;

public:
    BinarySearchTree() : raiz(nullptr) {}

    // Método para insertar un nuevo nodo en el árbol
    void insert(int valor) {
        Node* nuevo = new Node;
        nuevo->valor = valor;
        nuevo->izq = nullptr;
        nuevo->der = nullptr;

