                    if (actual->izq == nullptr) {
                        actual->izq = nuevo;
                        break;
                    }
                    actual = actual->izq;
                } else {
                    if (actual->der == nullptr) {
                        actual->der = nuevo;
                        break;
                    }
                    actual = actual->der;
                }
            }
        }
    }

