Here's an example of how you can manage sessions using Google OAuth in a React application using classes instead of effects, with Material Design:
```jsx
import React, { Component } from 'react';
import { Grid, TextField, Button } from '@material-ui/core';
import { GoogleLogin } from 'react-google-login';

class SessionManager extends Component {
  constructor(props) {
    super(props);
    this.state = {
      token: '',
      username: '',
      isLoggedIn: false
    };
  }

  handleGoogleLogin = (response) => {
    const { accessToken, profileObj } = response;
    const token = accessToken;
    const username = profileObj.name;
    this.setState({ token, username, isLoggedIn: true });
  }

  handleLogout = () => {
    this.setState({ token: '', username: '', isLoggedIn: false });
  }

  render() {
    return (
      <Grid container spacing={2}>
        {this.state.isLoggedIn ? (
          <Grid item xs={12}>
            <h2>Welcome, {this.state.username}!</h2>
            <Button onClick={this.handleLogout} variant="contained" color="primary">
              Logout
            </Button>
          </Grid>
        ) : (
          <Grid item xs={12}>
            <h2>Not logged in</h2>
            <GoogleLogin
              clientId="YOUR_CLIENT_ID"
              buttonText="Login with Google"
              onSuccess={this.handleGoogleLogin}
              onFailure={this.handleGoogleLogin}
              cookiePolicy="single_host_origin"
            />
          </Grid>
        )}
      </Grid>
    );
  }
}

export default SessionManager;
```
