```
// The tic tac toe board
let board = [
    ['1', '2', '3'],
    ['4', '5', '6'],
    ['7', '8', '9']
];

// The player's mark (X or O)
let player = 'X';

// The AI's mark (O)
let ai = 'O';

// The game's state
let gameState = {
    gameOver: false,
    winner: null
};

// Function to update the board
function updateBoard(row, col) {
    board[row-1][col-1] = player;
    if (checkWin()) {
        gameState.gameOver = true;
        gameState.winner = player;
    }
}

// Function to check if the player has won
function checkWin() {
    // Check rows
    for (let row = 0; row < 3; row++) {
        if (board[row][0] === player && board[row][1] === player && board[row][2] === player) {
            return true;
        }
    }
    // Check columns
    for (let col = 0; col < 3; col++) {
        if (board[0][col] === player && board[1][col] === player && board[2][col] === player) {
            return true;
        }
    }
    // Check diagonals
    if ((board[0][0] === player && board[1][1] === player && board[2][2] === player) ||
        (board[0][2] === player && board[1][1] === player && board[2][0] === player)) {
        return true;
    }
    return false;
}

// Function to generate a random move for the AI
function generateAiMove() {
    let possibleMoves = [];
    for (let row = 0; row < 3; row++) {
        for (let col = 0; col < 3; col++) {
            if (board[row][col] === ' ') {
                possibleMoves.push({ row, col });
            }
        }
    }
    if (possibleMoves.length > 0) {
        let randomMove = Math.floor(Math.random() * possibleMoves.length);
        return { row: possibleMoves[randomMove].row, col: possibleMoves[randomMove].col };
    } else {
        return null;
    }
}

// Function to make the AI's move
function makeAiMove() {
    let move = generateAiMove();
    if (move !== null) {
        board[move.row][move.col] = ai;
        if (checkWin()) {
            gameState.gameOver = true;
            gameState.winner = ai;
        }
    }
}

// The game loop
function playGame() {
    // Print the board
    console.log('  =>' + board[0][0] + '<=' + board[0][1] + '<=' + board[0][2]);
    console.log('  =>' + board[1][0] + '<=' + board[1][1] + '<=' + board[1][2]);
    console.log('  =>' + board[2][0] + '<=' + board[2][1] + '<=' + board[2][2]);
    console.log('');

    // Ask the player for their move
    let move = prompt('Enter your move (row and column, e.g. 1 1)');
    let row = parseInt(move.split(' ')[0]) - 1;
    let col = parseInt(move.split(' ')[1]) - 1;

    // Update the board and check if the player has won
    updateBoard(row, col);

    // If the player has won or the game is over, end the game
    if (gameState.gameOver) {
        console.log('Game Over! ' + gameState.winner + ' has won!');
        return;
    }

    // Make the AI's move
    makeAiMove();

    // If the AI has won or the game is over, end the game
    if (gameState.gameOver) {
        console.log('Game Over! ' + gameState.winner + ' has won!');
        return;
    }

    // Start a new game cycle
    playGame();
}

// Start the game
playGame();
